ST.xhtml:p:
stAlarm.iPriority := iPriority;

fbOn(IN := xCondition AND xEnable, PT := tOnDelay);
fbOff(IN := fbOn.Q, PT := tOffDelay);
stAlarm.xActive := fbOff.Q;

fbRise(CLK := stAlarm.xActive);
xNewAlarm := fbRise.Q;

IF xNewAlarm THEN
    stAlarm.xLatched := TRUE;
    stAlarm.xAcked := FALSE;
    stAlarm.rTimeInS := rNowS;
    stAlarm.iCount := stAlarm.iCount + 1;
END_IF

IF xAck AND stAlarm.xLatched THEN
    stAlarm.xAcked := TRUE;
END_IF

IF stAlarm.xLatched AND NOT stAlarm.xActive AND stAlarm.xAcked THEN
    stAlarm.xLatched := FALSE;
END_IF

fbStart(CLK := xExecute);

(* ---- initialise on the rising edge of the execute request ------------- *)
IF fbStart.Q THEN
    eStep := PS_LINEUP;
    rElapsedS := 0.0;
    rStepElapsedS := 0.0;
    rHoldAchievedS := 0.0;
    rConcSum := 0.0;
    rConcSamples := 0.0;
    xCharged := FALSE;
    xDone := FALSE;
    xFailed := FALSE;
    eFail := FC_NONE;
    stResult.ePhase := ePhase;
    stResult.xExecuted := TRUE;
    stResult.xPass := FALSE;
    stResult.eFail := FC_NONE;
    stResult.rDurationS := 0.0;
    stResult.rHoldAchievedS := 0.0;
    stResult.rMinTempC := 999.0;
    stResult.rMaxTempC := -999.0;
    stResult.rMinFlow := 999.0;
    stResult.rMeanConcPct := 0.0;
    stResult.rEndConductivity := 0.0;
    stResult.xAdaptiveEnd := FALSE;
    stResult.rWaterL := 0.0;
    stResult.rChemL := 0.0;
    stResult.rEnergyKWh := 0.0;
END_IF

rHoldRequiredS := TimeToSeconds(stParams.tHold);
rMinPhaseS     := TimeToSeconds(stParams.tMinPhase);
rMaxPhaseS     := TimeToSeconds(stParams.tMaxPhase);
rRecoverS      := TimeToSeconds(stParams.tRecover);

(* An adaptive phase is judged on the conductivity endpoint, so the hold
   requirement does not apply and the record should not imply that it does. *)
stResult.xAdaptiveEnd := stParams.xAdaptiveEnd;
IF stParams.xAdaptiveEnd THEN
    stResult.rHoldRequiredS := 0.0;
ELSE
    stResult.rHoldRequiredS := rHoldRequiredS;
END_IF

(* A recirculating phase makes its charge up in a closed loop through the
   balance tank and only sends the liquid to eReturn when it recovers at the
   end. A single-pass phase runs from the source straight to eReturn, on a
   small working volume so the tank washes out in about a minute. *)
xSinglePass := NOT stParams.xRecirculate;
IF xSinglePass THEN
    rFillTargetPct := C_RINSE_LEVEL_PCT;
ELSE
    rFillTargetPct := C_FILL_TARGET_PCT;
END_IF

IF stParams.xRecirculate AND (eStep <> PS_RECOVER) THEN
    eActiveReturn := RET_BALANCE;
ELSE
    eActiveReturn := stParams.eReturn;
END_IF

(* ---- idle: hold everything closed ------------------------------------ *)
IF NOT xExecute THEN
    stDemand.eSource := SRC_NONE;
    stDemand.eReturn := RET_DRAIN;
    stDemand.rFlowSp := 0.0;
    stDemand.rTempSp := 0.0;
    stDemand.xHeat := FALSE;
    stDemand.xDose := FALSE;
    stDemand.xSupplyPump := FALSE;
    stDemand.xReturnPump := FALSE;
    stDemand.xFillValve := FALSE;
    xInSpec := FALSE;
    RETURN;
END_IF

(* ---- criteria evaluated once, used by several steps ------------------- *)
xTempOk := (NOT stParams.xHeat) OR (rTempC >= stParams.rTempMin);
xFlowOk := rFlowM3h >= stParams.rFlowMin;
xConcOk := (NOT stParams.xDose) OR
           ((rConcPct >= stParams.rConcMin) AND (rConcPct <= stParams.rConcMax));
xInSpec := xTempOk AND xFlowOk AND xConcOk;

(* Dose whenever the strength has drifted below setpoint. Above the band the
   valve simply stays shut; the phase dilutes back with the next charge. *)
xDoseDemand := stParams.xDose AND (rConcPct < stParams.rConcSp);

(* ---- the line-up is common to every running step ---------------------- *)
stDemand.eSource := stParams.eSource;
stDemand.eReturn := eActiveReturn;
stDemand.rTempSp := stParams.rTempSp;
stDemand.rFlowSp := stParams.rFlowSp;

IF xHolding THEN
    (* Freeze: keep the valve matrix so the circuit stays full but stop
       circulating, stop heating and stop dosing. Accumulators do not advance,
       so a held phase does not earn hold time. *)
    stDemand.xSupplyPump := FALSE;
    stDemand.xReturnPump := TRUE;
    stDemand.xHeat := FALSE;
    stDemand.xDose := FALSE;
    stDemand.xFillValve := FALSE;
    RETURN;
END_IF

rElapsedS := rElapsedS + rCycleS;
rStepElapsedS := rStepElapsedS + rCycleS;
stResult.rDurationS := rElapsedS;

(* ---- the step machine ------------------------------------------------- *)
CASE eStep OF

    PS_LINEUP:
        stDemand.xSupplyPump := FALSE;
        stDemand.xReturnPump := TRUE;
        stDemand.xHeat := FALSE;
        stDemand.xDose := FALSE;
        stDemand.xFillValve := TRUE;
        IF rStepElapsedS >= 5.0 THEN
            eStep := PS_CHARGE;
            rStepElapsedS := 0.0;
        ELSIF rStepElapsedS > 60.0 THEN
            eFail := FC_LINEUP_TIMEOUT;
        END_IF

    PS_CHARGE:
        stDemand.xReturnPump := TRUE;
        stDemand.xFillValve := rLevelPct < rFillTargetPct;
        (* Start circulating as soon as there is enough suction head; the
           remaining fill and the dose trim happen while the pump runs, which
           is also what satisfies the no-dosing-without-flow interlock. *)
        stDemand.xSupplyPump := rLevelPct >= C_PUMP_START_PCT;
        stDemand.xHeat := stParams.xHeat AND stDemand.xSupplyPump;
        stDemand.xDose := xDoseDemand AND stDemand.xSupplyPump;
        xCharged := (rLevelPct >= rFillTargetPct) AND xConcOk;
        IF xCharged THEN
            eStep := PS_CIRCULATE;
            rStepElapsedS := 0.0;
        ELSIF rStepElapsedS > 600.0 THEN
            eFail := FC_CHARGE_TIMEOUT;
        END_IF

    PS_CIRCULATE:
        stDemand.xSupplyPump := TRUE;
        stDemand.xReturnPump := TRUE;
        stDemand.xHeat := stParams.xHeat;
        stDemand.xDose := xDoseDemand;
        (* Single-pass phases keep drawing fresh liquid; recirculating phases
           only top up if the circuit has swallowed some of the charge. *)
        stDemand.xFillValve := rLevelPct < rFillTargetPct;

        IF xInSpec THEN
            rHoldAchievedS := rHoldAchievedS + rCycleS;
        END_IF
        stResult.rHoldAchievedS := rHoldAchievedS;

        (* Statistics start once the loop has settled, otherwise every phase
           records the pump ramp as its minimum flow. *)
        IF rStepElapsedS > 15.0 THEN
            IF rTempC < stResult.rMinTempC THEN
                stResult.rMinTempC := rTempC;
            END_IF
            IF rTempC > stResult.rMaxTempC THEN
                stResult.rMaxTempC := rTempC;
            END_IF
            IF rFlowM3h < stResult.rMinFlow THEN
                stResult.rMinFlow := rFlowM3h;
            END_IF
            rConcSum := rConcSum + rConcPct;
            rConcSamples := rConcSamples + 1.0;
            stResult.rMeanConcPct := rConcSum / rConcSamples;
        END_IF
        stResult.rEndConductivity := rDeltaCond;

        (* Endpoint. An adaptive rinse stops when the return water is as clean
           as the water going in; everything else stops on verified hold time. *)
        fbEndStable(IN := stParams.xAdaptiveEnd AND (rDeltaCond <= stParams.rEndConductivity)
                          AND (rElapsedS >= rMinPhaseS),
                    PT := T#10s);

        IF stParams.xAdaptiveEnd THEN
            IF fbEndStable.Q THEN
                eStep := PS_RECOVER;
                rStepElapsedS := 0.0;
            ELSIF rElapsedS >= rMaxPhaseS THEN
                eFail := FC_RINSE_NOT_CLEAN;
            END_IF
        ELSE
            IF rHoldAchievedS >= rHoldRequiredS THEN
                eStep := PS_RECOVER;
                rStepElapsedS := 0.0;
            ELSIF rElapsedS >= rMaxPhaseS THEN
                eFail := FC_PHASE_TIMEOUT;
            END_IF
        END_IF

        (* Sustained excursions are faults, not just missing hold time. *)
        fbFlowLow(IN := NOT xFlowOk, PT := T#60s);
        IF fbFlowLow.Q THEN
            eFail := FC_FLOW_LOW;
        END_IF
        fbTempSlow(IN := stParams.xHeat AND NOT xTempOk, PT := T#8m);
        IF fbTempSlow.Q THEN
            eFail := FC_TEMP_TIMEOUT;
        END_IF
        IF rLevelPct < C_LEVEL_TRIP_PCT THEN
            eFail := FC_LEVEL_LOW;
        END_IF

    PS_RECOVER:
        (* Push the contents back where they came from. Heat and dose are off
           and the fill valve is shut, so the balance tank drains as the pump
           empties it into the return line. Draining it properly is what keeps
           the next phase's charge from being diluted by the last one's
           chemical and what keeps the following rinse short. *)
        stDemand.xSupplyPump := (rStepElapsedS < rRecoverS)
                                AND (rLevelPct > C_PUMP_START_PCT);
        stDemand.xReturnPump := TRUE;
        stDemand.xHeat := FALSE;
        stDemand.xDose := FALSE;
        stDemand.xFillValve := FALSE;
        IF (rStepElapsedS >= rRecoverS) OR (rLevelPct <= C_PUMP_START_PCT) THEN
            eStep := PS_DONE;
            rStepElapsedS := 0.0;
        END_IF

    PS_DONE:
        stDemand.xSupplyPump := FALSE;
        stDemand.xReturnPump := FALSE;
        stDemand.xHeat := FALSE;
        stDemand.xDose := FALSE;
        stDemand.xFillValve := FALSE;
        stDemand.eSource := SRC_NONE;
        xDone := TRUE;
        stResult.xPass := TRUE;
END_CASE

IF NOT xPumpHealthy THEN
    eFail := FC_PUMP_FAULT;
END_IF

IF eFail <> FC_NONE THEN
    xFailed := TRUE;
    xDone := FALSE;
    eStep := PS_DONE;
    stResult.xPass := FALSE;
    stResult.eFail := eFail;
    stDemand.xSupplyPump := FALSE;
    stDemand.xReturnPump := FALSE;
    stDemand.xHeat := FALSE;
    stDemand.xDose := FALSE;
    stDemand.xFillValve := FALSE;
END_IF

IF NOT xEnable THEN
    (* Bumpless enough for this duty: park the integrator and the output. *)
    rIntegral := 0.0;
    rOut := rOutMin;
    rError := 0.0;
    xSaturated := FALSE;
    xFirstScan := TRUE;
    rPrevPv := rPv;
    RETURN;
END_IF

rError := rSp - rPv;

(* Derivative on the measurement, so a setpoint step does not kick the valve. *)
IF xFirstScan THEN
    rDerivative := 0.0;
    xFirstScan := FALSE;
ELSIF rCycleS > 0.0 THEN
    rDerivative := (rPrevPv - rPv) / rCycleS;
ELSE
    rDerivative := 0.0;
END_IF
rPrevPv := rPv;

rRaw := rKp * rError + rIntegral + rKp * rTd * rDerivative;

(* Clamping anti-windup: integrate only if that does not push further into a
   limit the output is already sitting on. *)
IF rTi > 0.0 THEN
    IF (rRaw < rOutMax) AND (rRaw > rOutMin) THEN
        rIntegral := rIntegral + (rKp / rTi) * rError * rCycleS;
    ELSIF (rRaw >= rOutMax) AND (rError < 0.0) THEN
        rIntegral := rIntegral + (rKp / rTi) * rError * rCycleS;
    ELSIF (rRaw <= rOutMin) AND (rError > 0.0) THEN
        rIntegral := rIntegral + (rKp / rTi) * rError * rCycleS;
    END_IF
    rIntegral := LIMIT(rOutMin - rOutMax, rIntegral, rOutMax - rOutMin);
END_IF

rRaw := rKp * rError + rIntegral + rKp * rTd * rDerivative;
rOut := LIMIT(rOutMin, rRaw, rOutMax);
xSaturated := (rRaw > rOutMax) OR (rRaw < rOutMin);

fbFault(CLK := xFault);

IF fbFault.Q THEN
    xTripped := TRUE;
END_IF

IF xReset AND NOT xFault THEN
    xTripped := FALSE;
    xFeedbackFault := FALSE;
END_IF

xRun := xStart AND xInterlockOk AND NOT xTripped AND NOT xFeedbackFault;

(* Supervise only the commanded direction: a pump that keeps running after the
   command drops is a separate condition, alarmed in PRG_Alarms. *)
fbFeedback(IN := xRun AND NOT xRunFeedback, PT := tFeedbackTimeout);
IF fbFeedback.Q THEN
    xFeedbackFault := TRUE;
    xRun := FALSE;
END_IF

xHealthy := NOT xTripped AND NOT xFeedbackFault AND NOT xFault;

IF xReset THEN
    rTotal := 0.0;
END_IF

IF xEnable AND (rRatePerHour > rCutOff) THEN
    rRateUsed := rRatePerHour;
    rTotal := rTotal + rRatePerHour * rCycleS / 3600.0;
ELSE
    rRateUsed := 0.0;
END_IF

fbStart(CLK := xStart);
fbHold(CLK := xHold);
fbRestart(CLK := xRestart);
fbAbort(CLK := xAbort);
fbReset(CLK := xReset);

xStartPulse := FALSE;

(* An abort request or a safety trip pre-empts every other transition. *)
IF (fbAbort.Q OR xSafetyTrip OR xProcedureFailed)
   AND (eState <> UST_IDLE) AND (eState <> UST_COMPLETE)
   AND (eState <> UST_ABORTED) AND (eState <> UST_ABORTING) THEN
    eState := UST_ABORTING;
END_IF

CASE eState OF
    UST_IDLE:
        (* Park both settle timers so a previous batch cannot leave one
           already elapsed and collapse the next HOLDING into one scan. *)
        fbHoldTmr(IN := FALSE, PT := tHoldSettle);
        fbAbortTmr(IN := FALSE, PT := tAbortSettle);
        IF fbStart.Q AND xReadyToStart THEN
            eState := UST_STARTING;
        END_IF

    UST_STARTING:
        xStartPulse := TRUE;
        eState := UST_RUNNING;

    UST_RUNNING:
        IF xProcedureComplete THEN
            eState := UST_COMPLETING;
        ELSIF fbHold.Q THEN
            eState := UST_HOLDING;
        END_IF

    UST_HOLDING:
        fbHoldTmr(IN := TRUE, PT := tHoldSettle);
        IF fbHoldTmr.Q THEN
            fbHoldTmr(IN := FALSE, PT := tHoldSettle);
            eState := UST_HELD;
        END_IF

    UST_HELD:
        IF fbRestart.Q THEN
            eState := UST_RESTARTING;
        END_IF

    UST_RESTARTING:
        eState := UST_RUNNING;

    UST_COMPLETING:
        eState := UST_COMPLETE;

    UST_COMPLETE:
        IF fbReset.Q THEN
            eState := UST_IDLE;
        END_IF

    UST_ABORTING:
        fbAbortTmr(IN := TRUE, PT := tAbortSettle);
        IF fbAbortTmr.Q THEN
            fbAbortTmr(IN := FALSE, PT := tAbortSettle);
            eState := UST_ABORTED;
        END_IF

    UST_ABORTED:
        IF fbReset.Q AND NOT xSafetyTrip THEN
            eState := UST_IDLE;
        END_IF
END_CASE

xExecute  := (eState = UST_RUNNING);
(* RESTARTING counts as holding. It lasts one scan, and the phase has not
   resumed yet, so the phase engine must keep its state through it. Leaving it
   out of both outputs gives the engine one scan in which it is neither
   executing nor holding, which it reads as the phase having ended; the next
   scan then looks like a fresh start and the phase begins again from zero. *)
xHolding  := (eState = UST_HOLDING) OR (eState = UST_HELD) OR (eState = UST_RESTARTING);
xAborting := (eState = UST_ABORTING);
xActive   := (eState <> UST_IDLE) AND (eState <> UST_COMPLETE) AND (eState <> UST_ABORTED);

xCirculating := gxPhaseExecute AND (gPhaseStep = PS_CIRCULATE);
fbSafety(xCondition := gxSafetyTrip, iPriority := 1, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_SAFETY]);
fbSupplyPump(xCondition := xSupplyPumpFault OR (xSupplyPumpRun AND NOT xSupplyPumpRunning), iPriority := 1, tOnDelay := T#5s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_SUPPLY_PUMP]);
fbReturnPump(xCondition := xReturnPumpFault OR (xReturnPumpRun AND NOT xReturnPumpRunning), iPriority := 2, tOnDelay := T#5s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_RETURN_PUMP]);
fbLevelLow(xCondition := (rLevelBalanceTankPct < C_LEVEL_TRIP_PCT) AND (gUnitState <> UST_IDLE), iPriority := 2, tOnDelay := T#3s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_LEVEL_LOW]);
fbCausticLow(xCondition := rLevelCausticPct < C_CHEM_LEVEL_MIN, iPriority := 3, tOnDelay := T#10s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_CAUSTIC_LOW]);
fbAcidLow(xCondition := rLevelAcidPct < C_CHEM_LEVEL_MIN, iPriority := 3, tOnDelay := T#10s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_ACID_LOW]);
(* Twelve minutes: a cold circuit and a 1200 litre balance tank take about eight to come up to a wash temperature, so anything shorter alarms on every normal start. It still catches a steam valve that never opened. *) fbTempLow(xCondition := xCirculating AND gPhaseParams.xHeat AND (rTempReturnC < gPhaseParams.rTempMin), iPriority := 2, tOnDelay := T#12m, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_TEMP_LOW]);
fbFlowLow(xCondition := xCirculating AND (rFlowSupplyM3h < gPhaseParams.rFlowMin), iPriority := 2, tOnDelay := T#30s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_FLOW_LOW]);
fbCircuitBusy(xCondition := (NOT xCircuitAvailable) AND (gUnitState <> UST_IDLE), iPriority := 2, tOnDelay := T#3s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_CIRCUIT_BUSY]);
fbPhaseTimeout(xCondition := (gFailCode = FC_PHASE_TIMEOUT) OR (gFailCode = FC_CHARGE_TIMEOUT) OR (gFailCode = FC_TEMP_TIMEOUT), iPriority := 1, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_PHASE_TIMEOUT]);
fbNotClean(xCondition := gFailCode = FC_RINSE_NOT_CLEAN, iPriority := 1, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_NOT_CLEAN]);
fbNoSteam(xCondition := (NOT xSteamAvailable) AND gPhaseParams.xHeat AND gxPhaseExecute, iPriority := 3, tOnDelay := T#10s, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_NO_STEAM]);
fbCondSensor(xCondition := gxCondSensorFault, iPriority := 1, xAck := xCmdAckAlarms, rNowS := grPlcTimeS, stAlarm := gAlarms[C_ALM_COND_SENSOR]);
(* ---- summary ---------------------------------------------------------- *) giActiveAlarms := 0; gxAlarmP1Active := FALSE; xAnyLatched := FALSE; xHmiAlarmHorn := FALSE;
FOR i := 1 TO C_ALARM_COUNT DO IF gAlarms[i].xLatched THEN xAnyLatched := TRUE; giActiveAlarms := giActiveAlarms + 1; IF gAlarms[i].xActive AND (gAlarms[i].iPriority = 1) THEN gxAlarmP1Active := TRUE; END_IF IF NOT gAlarms[i].xAcked THEN xHmiAlarmHorn := TRUE; END_IF IF giFirstOut = 0 THEN giFirstOut := i; END_IF END_IF END_FOR
IF NOT xAnyLatched THEN giFirstOut := 0; END_IF
(* Acknowledge is momentary too and this is the last program that reads it. *) xCmdAckAlarms := FALSE;

(* ---- interlocked demands --------------------------------------------- *)
xRunSupply  := gDemand.xSupplyPump AND gxPermitRun;
xRunReturn  := gDemand.xReturnPump AND gxPermitRun;
xHeatDemand := gDemand.xHeat AND gxPermitHeat;
xDoseDemand := gDemand.xDose AND gxPermitDose;

(* ---- motor starters --------------------------------------------------- *)
fbSupplyPump(xStart       := xRunSupply,
             xInterlockOk := gxPermitRun,
             xRunFeedback := xSupplyPumpRunning,
             xFault       := xSupplyPumpFault,
             xReset       := xCmdReset);

fbReturnPump(xStart       := xRunReturn,
             xInterlockOk := gxPermitRun,
             xRunFeedback := xReturnPumpRunning,
             xFault       := xReturnPumpFault,
             xReset       := xCmdReset);

xSupplyPumpRun := fbSupplyPump.xRun;
xReturnPumpRun := fbReturnPump.xRun;

(* ---- flow loop -------------------------------------------------------- *)
fbFlowPid(xEnable := fbSupplyPump.xRun,
          rPv     := rFlowSupplyM3h,
          rSp     := gDemand.rFlowSp,
          rKp     := 3.0,
          rTi     := 8.0,
          rOutMin := C_PUMP_SPEED_MIN,
          rOutMax := C_PUMP_SPEED_MAX,
          rCycleS := C_CYCLE_S);

IF fbSupplyPump.xRun THEN
    rSupplyPumpSpeedPct := fbFlowPid.rOut;
ELSE
    rSupplyPumpSpeedPct := 0.0;
END_IF

(* ---- temperature loop -------------------------------------------------- *)
(* The controlled variable is the return temperature, not the supply. The
   recipe specifies a temperature at the soil and the coldest point of the
   circuit is the one that has to reach it; controlling the supply instead
   throttles the steam as soon as one pass through the plate pack looks hot
   enough and the loop then takes three times as long to bring the balance
   tank up.

   Tuning is lambda tuning for an integrator with dead time: the circuit holds
   450 litres, so at 18 m3/h a change at the plate pack takes about 90 seconds
   to reach the return element. Kp 5 %/K, Ti 600 s. *)
fbTempPid(xEnable := xHeatDemand,
          rPv     := rTempReturnC,
          rSp     := gDemand.rTempSp,
          rKp     := 5.0,
          rTi     := 600.0,
          rOutMin := 0.0,
          rOutMax := 100.0,
          rCycleS := C_CYCLE_S);

(* Override: a proportional-only high limit on the plate-pack outlet, low
   selected against the main loop. Proportional only on purpose, because an
   integrator on the losing half of a selector winds up. *)
fbSupplyLimit(xEnable := xHeatDemand,
              rPv     := rTempSupplyC,
              rSp     := C_SUPPLY_TEMP_LIMIT,
              rKp     := 25.0,
              rTi     := 0.0,
              rOutMin := 0.0,
              rOutMax := 100.0,
              rCycleS := C_CYCLE_S);

xSteamIsolation := xHeatDemand;
IF xHeatDemand THEN
    rSteamValvePct := MIN(fbTempPid.rOut, fbSupplyLimit.rOut);
ELSE
    rSteamValvePct := 0.0;
END_IF

(* ---- valve matrix ----------------------------------------------------- *)
(* Source selection. Only one inlet is ever open and the fill valve gates
   the whole group so a phase can hold its line-up without taking liquid. *)
xV01FreshWater     := gDemand.xFillValve AND (gDemand.eSource = SRC_FRESH);
xV02RecoveredWater := gDemand.xFillValve AND (gDemand.eSource = SRC_RECOVERED);
xV11CausticSupply  := gDemand.xFillValve AND (gDemand.eSource = SRC_CAUSTIC);
xV12AcidSupply     := gDemand.xFillValve AND (gDemand.eSource = SRC_ACID);

(* Dosing is concentrate trim on top of whatever the tank already holds, so it
   is gated on the phase's dose demand rather than on the fill valve. *)
xV03CausticDose    := xDoseDemand AND (gDemand.eSource = SRC_CAUSTIC);
xV04AcidDose       := xDoseDemand AND (gDemand.eSource = SRC_ACID);

xV08ReturnToCaustic := FALSE;
xV10ReturnToAcid := FALSE;

(* Return destination. Exactly one of these is open whenever the return pump
   is running, so the circuit always has somewhere to discharge. *)
xV06ReturnToDrain    := FALSE;
xV07ReturnToBalance  := FALSE;
xV09ReturnToRecovery := FALSE;

CASE gDemand.eReturn OF
    RET_DRAIN:
        xV06ReturnToDrain := TRUE;
    RET_RECOVERY:
        xV09ReturnToRecovery := TRUE;
    RET_CAUSTIC:
        xV08ReturnToCaustic := TRUE;
    RET_ACID:
        xV10ReturnToAcid := TRUE;
    RET_BALANCE:
        xV07ReturnToBalance := TRUE;
END_CASE

xV05SupplyToCircuit := fbSupplyPump.xRun;

xUnitActive := (gUnitState <> UST_IDLE)
               AND (gUnitState <> UST_COMPLETE)
               AND (gUnitState <> UST_ABORTED);

(* ---- instantaneous steam duty ---------------------------------------- *)
IF xSteamIsolation AND (rTempSupplyC > rTempBalanceTankC) THEN
    rEnergyKW := rFlowSupplyM3h * 1000.0 / 3600.0 * 4.19 * (rTempSupplyC - rTempBalanceTankC);
ELSE
    rEnergyKW := 0.0;
END_IF

(* ---- totalisers, all reset together at the start of a batch ------------
    Each is gated on the line-up rather than on a valve command. That
    distinction matters more than it looks.

    Make-up is bang-bang level control on a break tank, so V01 and V02 toggle
    every scan or two. The flow transmitter is read at the top of the scan and
    therefore reports the previous scan's flow, so gating the totaliser on the
    valve command aliases the two signals: on the scans the valve is open the
    meter is still reporting the scan it was shut, so the total comes out
    about a fifth low. The source selection only changes at a phase boundary
    and the meter reads zero when the valve is shut in any case. Gating on
    the source and letting the low-flow cut-off reject the noise measures
    what actually went through the meter.
*)
fbFresh(xEnable := gDemand.eSource = SRC_FRESH,
        rRatePerHour := rFlowMakeupM3h * 1000.0,
        rCutOff := 50.0,
        rCycleS := C_CYCLE_S,
        xReset := gxCycleReset);

fbRecovered(xEnable := gDemand.eSource = SRC_RECOVERED,
            rRatePerHour := rFlowMakeupM3h * 1000.0,
            rCutOff := 50.0,
            rCycleS := C_CYCLE_S,
            xReset := gxCycleReset);

fbEffluent(xEnable := xV06ReturnToDrain,
           rRatePerHour := rFlowSupplyM3h * 1000.0,
           rCutOff := 50.0,
           rCycleS := C_CYCLE_S,
           xReset := gxCycleReset);

fbCaustic(xEnable := xV03CausticDose,
          rRatePerHour := C_CAUSTIC_DOSE_LPM * 60.0,
          rCycleS := C_CYCLE_S,
          xReset := gxCycleReset);

fbAcid(xEnable := xV04AcidDose,
       rRatePerHour := C_ACID_DOSE_LPM * 60.0,
       rCycleS := C_CYCLE_S,
       xReset := gxCycleReset);

fbEnergy(xEnable := xSteamIsolation,
         rRatePerHour := rEnergyKW,
         rCycleS := C_CYCLE_S,
         xReset := gxCycleReset);

gKpi.rFreshWaterL     := fbFresh.rTotal;
gKpi.rRecoveredWaterL := fbRecovered.rTotal;
gKpi.rEffluentL       := fbEffluent.rTotal;
gKpi.rCausticL        := fbCaustic.rTotal;
gKpi.rAcidL           := fbAcid.rTotal;
gKpi.rEnergyKWh       := fbEnergy.rTotal;

IF gxCycleReset THEN
    grCycleElapsedS := 0.0;
    gKpi.xVerifiedClean := FALSE;
    rSnapWater := 0.0;
    rSnapChem := 0.0;
    rSnapEnergy := 0.0;
END_IF

IF xUnitActive THEN
    grCycleElapsedS := grCycleElapsedS + C_CYCLE_S;
END_IF
gKpi.rCycleTimeS := grCycleElapsedS;

(* ---- per-phase consumption, by difference ----------------------------- *)
IF gxPhaseStartPulse THEN
    rSnapWater  := fbFresh.rTotal + fbRecovered.rTotal;
    rSnapChem   := fbCaustic.rTotal + fbAcid.rTotal;
    rSnapEnergy := fbEnergy.rTotal;
END_IF

IF gxPhaseEndPulse AND (giPhaseIndex >= 1) AND (giPhaseIndex <= C_PHASE_COUNT) THEN
    gResults[giPhaseIndex].rWaterL := fbFresh.rTotal + fbRecovered.rTotal - rSnapWater;
    gResults[giPhaseIndex].rChemL := fbCaustic.rTotal + fbAcid.rTotal - rSnapChem;
    gResults[giPhaseIndex].rEnergyKWh := fbEnergy.rTotal - rSnapEnergy;
END_IF

(* ---- release criteria -------------------------------------------------- *)
(* A batch is only released if every phase that ran met its own criteria and
   the final rinse came back as clean as the water going in. A fixed-time
   recipe can complete without satisfying the second test and that is the
   whole argument for the adaptive one. *)
xAllPass := TRUE;
FOR i := 1 TO C_PHASE_COUNT DO
    IF gResults[i].xExecuted AND NOT gResults[i].xPass THEN
        xAllPass := FALSE;
    END_IF
END_FOR

xFinalRinseOk := gResults[5].xExecuted
                 AND gResults[5].xPass
                 AND (gResults[5].rEndConductivity <= gRecipe.rRinseEndCond);

IF gUnitState = UST_COMPLETE THEN
    gKpi.xVerifiedClean := xAllPass AND xFinalRinseOk;
END_IF

(* ---- SCADA image ------------------------------------------------------- *)
iHmiUnitState        := TO_INT(gUnitState);
iHmiPhase            := TO_INT(gPhase);
iHmiPhaseStep        := TO_INT(gPhaseStep);
iHmiFailCode         := TO_INT(gFailCode);
iHmiActiveAlarms     := giActiveAlarms;
iHmiFirstOutAlarm    := giFirstOut;
iHmiBatchId          := giBatchId;

rHmiFreshWaterL      := gKpi.rFreshWaterL;
rHmiRecoveredWaterL  := gKpi.rRecoveredWaterL;
rHmiEffluentL        := gKpi.rEffluentL;
rHmiCausticL         := gKpi.rCausticL;
rHmiAcidL            := gKpi.rAcidL;
rHmiEnergyKWh        := gKpi.rEnergyKWh;
rHmiCycleTimeS       := gKpi.rCycleTimeS;
rHmiPhaseElapsedS    := grPhaseElapsedS;
rHmiHoldAchievedS    := grHoldAchievedS;
rHmiConcentrationPct := grConcentrationPct;

xHmiVerifiedClean    := gKpi.xVerifiedClean;
xHmiCycleComplete    := gUnitState = UST_COMPLETE;
xHmiCycleAborted     := gUnitState = UST_ABORTED;
xHmiHeating          := xSteamIsolation;

grPlcTimeS := grPlcTimeS + C_CYCLE_S;

(* A running pump moving nothing is either dry or dead-headed. Either way it
   destroys the seal in minutes, so it is a latch-free hard stop. *)
fbDryRun(IN := xSupplyPumpRunning AND (rFlowSupplyM3h < C_DRY_RUN_FLOW), PT := T#20s);

fbCircuitLost(IN := NOT xCircuitAvailable, PT := T#3s);

gxSafetyTrip := (NOT xSafetyOk)
                OR xBalanceTankLowLow
                OR fbDryRun.Q
                OR (gUnitState <> UST_IDLE AND fbCircuitLost.Q);

gxPermitRun := xSafetyOk
               AND (NOT xBalanceTankLowLow)
               AND (NOT fbDryRun.Q)
               AND xCircuitAvailable
               AND (rLevelBalanceTankPct > C_LEVEL_TRIP_PCT);

gxPermitHeat := gxPermitRun
                AND xSteamAvailable
                AND xSupplyPumpRunning
                AND (rFlowSupplyM3h >= C_MIN_FLOW_HEAT);

(* Only the tank the current phase is drawing from has to have stock. *)
CASE gDemand.eSource OF
    SRC_CAUSTIC:
        xChemStockOk := rLevelCausticPct > C_CHEM_LEVEL_MIN;
    SRC_ACID:
        xChemStockOk := rLevelAcidPct > C_CHEM_LEVEL_MIN;
ELSE
    xChemStockOk := TRUE;
END_CASE

gxPermitDose := gxPermitRun AND xSupplyPumpRunning AND xChemStockOk;

rFlowLps := MAX(rFlowSpM3h, 1.0) * 1000.0 / 3600.0;
rTurnoverS := C_RINSE_TURNOVERS * C_CIRCUIT_VOLUME_L / rFlowLps;
RinseBlankTime := SecondsToTime(MAX(TimeToSeconds(tFloor), rTurnoverS));

CASE eCurrent OF
    PH_IDLE:
        NextPhase := PH_PRE_RINSE;
    PH_PRE_RINSE:
        NextPhase := PH_CAUSTIC_WASH;
    PH_CAUSTIC_WASH:
        NextPhase := PH_INTERMEDIATE_RINSE;
    PH_INTERMEDIATE_RINSE:
        IF xUseAcid THEN
            NextPhase := PH_ACID_WASH;
        ELSE
            NextPhase := PH_FINAL_RINSE;
        END_IF
    PH_ACID_WASH:
        NextPhase := PH_FINAL_RINSE;
    PH_FINAL_RINSE:
        IF xUseSanitise THEN
            NextPhase := PH_SANITISE;
        ELSE
            NextPhase := PH_COMPLETE;
        END_IF
    PH_SANITISE:
        NextPhase := PH_COMPLETE;
ELSE
    NextPhase := PH_COMPLETE;
END_CASE

(* ---------------------------------------------------------------------- *)
(* 1. Unit state machine                                                    *)
(* ---------------------------------------------------------------------- *)
xReadyToStart := (NOT gxSafetyTrip) AND xCircuitAvailable AND (NOT gxAlarmP1Active);

fbUnit(xStart              := xCmdStart,
       xHold               := xCmdHold,
       xRestart            := xCmdRestart,
       xAbort              := xCmdAbort,
       xReset              := xCmdReset,
       xReadyToStart       := xReadyToStart,
       xProcedureComplete  := xProcComplete,
       xProcedureFailed    := xProcFailed,
       xSafetyTrip         := gxSafetyTrip);

gUnitState := fbUnit.eState;

(* ---------------------------------------------------------------------- *)
(* 2. Start of batch                                                        *)
(* ---------------------------------------------------------------------- *)
gxCycleReset := FALSE;
IF fbUnit.xStartPulse THEN
    giBatchId := giBatchId + 1;
    gPhase := PH_PRE_RINSE;
    gFailCode := FC_NONE;
    xProcComplete := FALSE;
    xProcFailed := FALSE;
    xPhaseGap := FALSE;
    gxCycleReset := TRUE;
    gxCondSensorFault := FALSE;
    gxCondProven := FALSE;
    FOR iPhaseIndex := 1 TO C_PHASE_COUNT DO
        gResults[iPhaseIndex].ePhase := PH_IDLE;
        gResults[iPhaseIndex].xExecuted := FALSE;
        gResults[iPhaseIndex].xPass := FALSE;
        gResults[iPhaseIndex].eFail := FC_NONE;
        gResults[iPhaseIndex].rDurationS := 0.0;
        gResults[iPhaseIndex].rHoldAchievedS := 0.0;
        gResults[iPhaseIndex].rWaterL := 0.0;
        gResults[iPhaseIndex].rChemL := 0.0;
        gResults[iPhaseIndex].rEnergyKWh := 0.0;
    END_FOR
END_IF

IF fbUnit.eState = UST_IDLE THEN
    gPhase := PH_IDLE;
    gFailCode := FC_NONE;
END_IF

(* ---------------------------------------------------------------------- *)
(* 3. Phase parameters from the recipe                                      *)
(* ---------------------------------------------------------------------- *)
gPhaseParams.rFlowSp  := gRecipe.rFlowSp;
gPhaseParams.rFlowMin := gRecipe.rFlowMin;
gPhaseParams.tMaxPhase := gRecipe.tPhaseMax;
gPhaseParams.tMinPhase := T#30s;
gPhaseParams.xAdaptiveEnd := FALSE;
gPhaseParams.rEndConductivity := gRecipe.rRinseEndCond;
gPhaseParams.rConcSp := 0.0;
gPhaseParams.rConcMin := 0.0;
gPhaseParams.rConcMax := 0.0;
gPhaseParams.rTempSp := 0.0;
gPhaseParams.rTempMin := 0.0;
gPhaseParams.xHeat := FALSE;
gPhaseParams.xDose := FALSE;
gPhaseParams.xRecirculate := FALSE;

CASE gPhase OF

    PH_PRE_RINSE:
        (* Recovered final-rinse water if there is any, mains if not. This one
           line is most of the water saving: the pre-rinse is the biggest
           single-pass consumer in the cycle. *)
        IF rLevelRecoveryPct > 25.0 THEN
            gPhaseParams.eSource := SRC_RECOVERED;
        ELSE
            gPhaseParams.eSource := SRC_FRESH;
        END_IF
        gPhaseParams.eReturn := RET_DRAIN;
        gPhaseParams.tHold := gRecipe.tPreRinse;
        gPhaseParams.tMinPhase := RinseBlankTime(gRecipe.tRinseMin, gRecipe.rFlowSp);
        gPhaseParams.tRecover := T#20s;
        gPhaseParams.tMaxPhase := gRecipe.tRinseMax;
        gPhaseParams.xAdaptiveEnd := gRecipe.xAdaptive;
        (* Gross soil removal: a looser endpoint than the final rinse. *)
        gPhaseParams.rEndConductivity := gRecipe.rRinseEndCond * 3.0;

    PH_CAUSTIC_WASH:
        gPhaseParams.eSource := SRC_CAUSTIC;
        gPhaseParams.eReturn := RET_CAUSTIC;
        gPhaseParams.xRecirculate := TRUE;
        gPhaseParams.rTempSp := gRecipe.rCausticTempSp;
        gPhaseParams.rTempMin := gRecipe.rCausticTempMin;
        gPhaseParams.xHeat := TRUE;
        gPhaseParams.rConcSp := gRecipe.rCausticConcSp;
        gPhaseParams.rConcMin := gRecipe.rCausticConcSp - 0.25;
        gPhaseParams.rConcMax := gRecipe.rCausticConcSp + 0.50;
        gPhaseParams.xDose := TRUE;
        gPhaseParams.tHold := gRecipe.tCausticHold;
        gPhaseParams.tMinPhase := T#1m;
        gPhaseParams.tRecover := T#180s;

    PH_INTERMEDIATE_RINSE:
        gPhaseParams.eSource := SRC_FRESH;
        gPhaseParams.eReturn := RET_DRAIN;
        gPhaseParams.tHold := gRecipe.tIntRinse;
        gPhaseParams.tMinPhase := RinseBlankTime(gRecipe.tRinseMin, gRecipe.rFlowSp);
        gPhaseParams.tRecover := T#20s;
        gPhaseParams.tMaxPhase := gRecipe.tRinseMax;
        gPhaseParams.xAdaptiveEnd := gRecipe.xAdaptive;
        gPhaseParams.rEndConductivity := gRecipe.rRinseEndCond * 2.0;

    PH_ACID_WASH:
        gPhaseParams.eSource := SRC_ACID;
        gPhaseParams.eReturn := RET_ACID;
        gPhaseParams.xRecirculate := TRUE;
        gPhaseParams.rTempSp := gRecipe.rAcidTempSp;
        gPhaseParams.rTempMin := gRecipe.rAcidTempMin;
        gPhaseParams.xHeat := TRUE;
        gPhaseParams.rConcSp := gRecipe.rAcidConcSp;
        gPhaseParams.rConcMin := gRecipe.rAcidConcSp - 0.15;
        gPhaseParams.rConcMax := gRecipe.rAcidConcSp + 0.35;
        gPhaseParams.xDose := TRUE;
        gPhaseParams.tHold := gRecipe.tAcidHold;
        gPhaseParams.tMinPhase := T#1m;
        gPhaseParams.tRecover := T#180s;

    PH_FINAL_RINSE:
        gPhaseParams.eSource := SRC_FRESH;
        gPhaseParams.eReturn := RET_RECOVERY;
        gPhaseParams.tHold := gRecipe.tFinalRinse;
        gPhaseParams.tMinPhase := RinseBlankTime(gRecipe.tRinseMin, gRecipe.rFlowSp);
        gPhaseParams.tRecover := T#30s;
        gPhaseParams.tMaxPhase := gRecipe.tRinseMax;
        gPhaseParams.xAdaptiveEnd := gRecipe.xAdaptive;
        gPhaseParams.rEndConductivity := gRecipe.rRinseEndCond;

    PH_SANITISE:
        gPhaseParams.eSource := SRC_FRESH;
        gPhaseParams.eReturn := RET_BALANCE;
        gPhaseParams.xRecirculate := TRUE;
        gPhaseParams.rTempSp := gRecipe.rSanitiseTempSp;
        gPhaseParams.rTempMin := gRecipe.rSanitiseTempMin;
        gPhaseParams.xHeat := TRUE;
        gPhaseParams.tHold := gRecipe.tSanitiseHold;
        gPhaseParams.tMinPhase := T#1m;
        gPhaseParams.tRecover := T#30s;

ELSE
    gPhaseParams.eSource := SRC_NONE;
    gPhaseParams.eReturn := RET_DRAIN;
    gPhaseParams.tHold := T#0s;
    gPhaseParams.tRecover := T#0s;
END_CASE

(* ---------------------------------------------------------------------- *)
(* 3b. Derived measurements                                                 *)
(* ---------------------------------------------------------------------- *)
(* Both are computed here rather than in PRG_Control so the phase engine sees
   this scan's values instead of the previous scan's. The transmitter already
   compensates to 25 degC, so the calibration is a straight division. *)
grDeltaConductivity := rConductivityReturn - rConductivitySupply;

(* Strength is measured in the balance tank, not on the return line: during
   the charge step there is no established return flow to read. *)
CASE gPhaseParams.eSource OF
    SRC_CAUSTIC:
        grConcentrationPct := rConductivityTank / C_COND_K_CAUSTIC;
        grCondFloor := 0.5 * gPhaseParams.rConcSp * C_COND_K_CAUSTIC;
    SRC_ACID:
        grConcentrationPct := rConductivityTank / C_COND_K_ACID;
        grCondFloor := 0.5 * gPhaseParams.rConcSp * C_COND_K_ACID;
ELSE
    grConcentrationPct := 0.0;
    grCondFloor := 0.0;
END_CASE

(* ---------------------------------------------------------------------- *)
(* 4. Run the phase engine                                                  *)
(* ---------------------------------------------------------------------- *)
(* The engine stays executing through a hold so that it keeps its step, its
   elapsed time and its verified hold time. Dropping xExecute instead would
   look like the end of the phase and the restart would look like a fresh
   rising edge and begin the phase again from zero. *)
xPhaseActive := (fbUnit.xExecute OR fbUnit.xHolding)
                AND (gPhase <> PH_IDLE)
                AND (gPhase <> PH_COMPLETE)
                AND (NOT xPhaseGap);
xExecutePhase := xPhaseActive AND (NOT fbUnit.xHolding);

fbPhase(xExecute     := xPhaseActive,
        xHolding     := fbUnit.xHolding,
        ePhase       := gPhase,
        stParams     := gPhaseParams,
        rTempC       := rTempReturnC,
        rFlowM3h     := rFlowSupplyM3h,
        rConcPct     := grConcentrationPct,
        rDeltaCond   := grDeltaConductivity,
        rLevelPct    := rLevelBalanceTankPct,
        xPumpHealthy := NOT xSupplyPumpFault,
        rCycleS      := C_CYCLE_S);

gPhaseStep := fbPhase.eStep;
gDemand := fbPhase.stDemand;
grPhaseElapsedS := fbPhase.rElapsedS;
grHoldAchievedS := fbPhase.rHoldAchievedS;
gxPhaseExecute := xExecutePhase;
gxPhaseDone := fbPhase.xDone;
gxPhaseFailed := fbPhase.xFailed;

(*
    Plausibility check on the return conductivity element.

    Every rinse endpoint rests on this one transmitter; so does the
    release decision. The dangerous failure is not a dead reading but a
    reading stuck at something clean: an endpoint satisfied before the
    rinse began would pass a dirty circuit.

    There is one point in the cycle where the process guarantees a large
    signal. Circulating a wash at strength, the return line is full of
    detergent, so the element must at some point read at least half the
    expected value. A wash that finishes without it having done so means
    the element is not reading the process. Nothing may be released on its
    word.

    Written as a latch rather than a timer so that it holds for any hold
    time: a two minute wash proves the element as well as a twenty minute
    one. Both washes precede both rinses, so the check always runs before
    an endpoint is trusted.
*)
IF gxPhaseExecute
   AND (gPhaseStep = PS_CIRCULATE)
   AND (grCondFloor > 0.0)
   AND (rConductivityReturn >= grCondFloor) THEN
    gxCondProven := TRUE;
END_IF

(* ---------------------------------------------------------------------- *)
(* 5. Phase transitions and the batch record                                *)
(* ---------------------------------------------------------------------- *)
gxPhaseStartPulse := FALSE;
gxPhaseEndPulse := FALSE;
xPhaseGap := FALSE;

IF gPhase <> ePrevPhase THEN
    ePrevPhase := gPhase;
    IF (gPhase <> PH_IDLE) AND (gPhase <> PH_COMPLETE) THEN
        gxPhaseStartPulse := TRUE;
        gxCondProven := FALSE;
    END_IF
END_IF

iResultIndex := TO_INT(gPhase);

IF xExecutePhase AND fbPhase.xDone THEN
    gResults[iResultIndex] := fbPhase.stResult;
    gxPhaseEndPulse := TRUE;
    giPhaseIndex := iResultIndex;
    gPhase := NextPhase(gPhase, gRecipe.xUseAcid, gRecipe.xUseSanitise);
    xPhaseGap := TRUE;
END_IF

IF gxPhaseEndPulse AND (grCondFloor > 0.0) AND (NOT gxCondProven) THEN
    gxCondSensorFault := TRUE;
END_IF

IF gxCondSensorFault AND (gFailCode = FC_NONE) THEN
    gFailCode := FC_SENSOR_FAULT;
    xProcFailed := TRUE;
END_IF

IF xExecutePhase AND fbPhase.xFailed THEN
    gResults[iResultIndex] := fbPhase.stResult;
    gxPhaseEndPulse := TRUE;
    giPhaseIndex := iResultIndex;
    gFailCode := fbPhase.eFail;
    xProcFailed := TRUE;
END_IF

IF (gPhase = PH_COMPLETE) AND (fbUnit.eState = UST_RUNNING) THEN
    xProcComplete := TRUE;
END_IF

IF fbUnit.xAborting AND (gFailCode = FC_NONE) THEN
    IF gxSafetyTrip THEN
        gFailCode := FC_SAFETY_TRIP;
    ELSE
        gFailCode := FC_OPERATOR_ABORT;
    END_IF
END_IF

IF fbUnit.eState = UST_ABORTED THEN
    xProcFailed := FALSE;    (* consumed; the state machine is already there *)
END_IF

(* Momentary commands. The edges were taken at the top of this program, so the
   bits are cleared here and a client only ever has to set one. *)
xCmdStart := FALSE;
xCmdHold := FALSE;
xCmdRestart := FALSE;
xCmdAbort := FALSE;
xCmdReset := FALSE;
